&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Financial  &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;$20/pay period cell phone reimbursement&lt;/span&gt;&lt;/li&gt;
